const createRateLimiter = require('./rateLimiter');

function validateRecipient(user) {
  if (!user || typeof user !== 'object') {
    throw new TypeError('user is required');
  }
  if (!user.id) {
    throw new TypeError('user.id is required');
  }
}

function validateMessage(message) {
  if (!message || typeof message !== 'object') {
    throw new TypeError('message is required');
  }
  if (!message.title || !message.body) {
    throw new TypeError('message.title and message.body are required');
  }
}

function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || 'there')
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, message.category || 'general');
}

/**
 * Composes the shared send pipeline with a channel strategy.
 *
 * `createChannel(options, { now })` must return:
 *   name               channel id used in payload ids, results, and throttle keys
 *   defaultMaxPerHour  hourly limit used when options.maxPerHour is not set
 *   validateUser(user)                                       checks beyond user.id
 *   shouldThrottle(rateLimiter, user, message, sendOptions)  throttle policy
 *   format(base, user, message, sendOptions)                 channel payload from the base payload
 *   deliver(transport, payload)                              hands the payload to the transport
 */
function createChannelNotifier(createChannel, options = {}) {
  const transport = options.transport || {};
  const now = options.now || (() => new Date());
  const defaultLocale = options.defaultLocale || 'en-US';
  const channel = createChannel(options, { now });
  const rateLimiter = createRateLimiter({
    channel: channel.name,
    store: options.throttleStore || new Map(),
    maxPerHour: options.maxPerHour || channel.defaultMaxPerHour,
    now
  });

  function validateUser(user) {
    validateRecipient(user);
    channel.validateUser(user);
  }

  function shouldThrottle(user, message, sendOptions = {}) {
    return channel.shouldThrottle(rateLimiter, user, message, sendOptions);
  }

  function format(user, message, sendOptions = {}) {
    const id = `${channel.name}-${user.id}-${now().getTime()}`;
    const locale = sendOptions.locale || user.locale || defaultLocale;
    const title = applyTemplate(message.title, user, message);
    const body = applyTemplate(message.body, user, message);

    const base = {
      id,
      channel: channel.name,
      locale,
      title,
      body,
      preview: `${title}: ${body}`.slice(0, 120),
      metadata: {
        category: message.category || 'general',
        priority: message.priority || 'normal',
        generatedAt: now().toISOString()
      }
    };

    return channel.format(base, user, message, sendOptions);
  }

  async function deliver(payload) {
    await channel.deliver(transport, payload);
  }

  function recordDelivery(user, message) {
    rateLimiter.record(user, message);
  }

  async function send(user, message, sendOptions = {}) {
    validateUser(user);
    validateMessage(message);

    const throttle = shouldThrottle(user, message, sendOptions);
    if (throttle.throttled) {
      return {
        channel: channel.name,
        status: 'throttled',
        reason: throttle.reason,
        retryAt: throttle.retryAt,
        userId: user.id
      };
    }

    const formatted = format(user, message, sendOptions);
    await deliver(formatted);
    recordDelivery(user, message);

    return {
      channel: channel.name,
      status: 'sent',
      userId: user.id,
      id: formatted.id,
      preview: formatted.preview
    };
  }

  return {
    channel: channel.name,
    send,
    validateUser,
    validateMessage,
    shouldThrottle,
    format,
    deliver,
    recordDelivery
  };
}

module.exports = createChannelNotifier;
function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function createEmailChannel(options) {
  const from = options.from || 'noreply@example.com';
  const replyTo = options.replyTo || 'support@example.com';
  const unsubscribeBaseUrl = options.unsubscribeBaseUrl || 'https://example.com/unsubscribe';

  function footerFor(user, message) {
    if (message.category === 'transactional' || message.category === 'security') {
      return `Sent to ${user.email} because of recent account activity.`;
    }
    const url = `${unsubscribeBaseUrl}?user=${encodeURIComponent(user.id)}`;
    return `You can unsubscribe at ${url}.`;
  }

  return {
    name: 'email',
    defaultMaxPerHour: 8,

    validateUser(user) {
      if (!user.email || !user.email.includes('@')) {
        throw new TypeError('user.email is required for email notifications');
      }
    },

    shouldThrottle(rateLimiter, user, message, sendOptions) {
      const limit = rateLimiter.check(user, message, sendOptions);
      if (limit.throttled) {
        return limit;
      }

      if (message.category === 'marketing' && !user.emailOptIn) {
        return {
          throttled: true,
          reason: 'user has not opted into marketing email',
          retryAt: null
        };
      }

      return { throttled: false };
    },

    format(base, user, message) {
      const subjectPrefix = message.category === 'security' ? '[Action Required] ' : '';
      const footer = footerFor(user, message);

      return {
        ...base,
        to: user.email,
        from,
        replyTo,
        subject: `${subjectPrefix}${base.title}`,
        text: `${base.body}\n\n${footer}`,
        html: `<h1>${escapeHtml(base.title)}</h1><p>${escapeHtml(base.body)}</p><footer>${escapeHtml(footer)}</footer>`,
        preview: base.body.slice(0, 90)
      };
    },

    async deliver(transport, payload) {
      if (typeof transport.email !== 'function') {
        throw new Error('email transport is not configured');
      }
      await transport.email(payload);
    }
  };
}

module.exports = createEmailChannel;
function createInAppChannel(options, { now }) {
