  const defaultAction = options.defaultAction || '/notifications';

  return {
    name: 'inapp',
    defaultMaxPerHour: 50,

    validateUser(user) {
      if (user.disabledInApp) {
        throw new TypeError('in-app notifications are disabled for this user');
      }
    },

    shouldThrottle(rateLimiter, user, message, sendOptions) {
      if (message.category === 'security') {
        return { throttled: false };
