  const defaultChannel = options.defaultChannel || '#general';

  return {
    name: 'slack',
    defaultMaxPerHour: 20,

    validateUser(user) {
      if (!user.slackId && !user.slackChannel) {
        throw new TypeError('user.slackId or user.slackChannel is required for Slack notifications');
      }
    },

    shouldThrottle(rateLimiter, user, message, sendOptions) {
      if (sendOptions.threadTs) {
        return { throttled: false };
      }
      return rateLimiter.check(user, message, sendOptions);
    },

    format(base, user, message, sendOptions) {
      const channel = sendOptions.channel || user.slackChannel || defaultChannel;
      const mention = user.slackId ? `<@${user.slackId}> ` : '';
      const text = `${mention}*${base.title}*\n${base.body}`;

      return {
        ...base,
        workspace: user.slackWorkspace || defaultWorkspace,
        channel,
        threadTs: sendOptions.threadTs || null,
        text,
        blocks: blocksFor(base, mention),
        preview: text.replace(/\*/g, '').slice(0, 120)
      };
    },

    async deliver(transport, payload) {
      if (typeof transport.slack !== 'function') {
        throw new Error('slack transport is not configured');
      }
      await transport.slack(payload);
    }
  };
}

